return {
  feint: {
    hook: "onEvent",
    eventType: "swordFeint",
    async promptOnPlayer(H, actor) {
      const target = await H.ask.hunterInZone(H.zone.of(actor), "Noble: choose a Hunter to guard");
      if (!target) return false;
      await H.actions.grantManoeuvre(target, "guard");
      return true;
    },
  },
};

return {
  feint: {
    hook: "activated", label: "Feint", rateLimit: "oncePerTurn",
    async run(H, actor, ctx) {
      const zone = H.zone.of(actor);
      if (!zone) {
        ui.notifications.warn("Your token is not inside a zone region.");
        return false;
      }
      if (!(await H.threat.place(actor, zone, 2, { source: "ability", reason: "Feint" }))) {
        ui.notifications.warn("Unable to place Threat in this zone.");
        return false;
      }
      await H.chat.post(actor.name + " Feints with " + ctx.item.name + " in " + zone + ". Threat: +2.", actor);
      await H.events.swordFeint(actor);
    },
  },
};

if (!ctx.byOwner) return false;
if (!H.zone.isClose(ctx.toZone)) return false;
await H.effects.apply([{ type: "damageEntity", resolve: 1, label: "Charge" }], ctx);

const flag = "skirmisherBonus";
return {
  move: {
    hook: "onMove", ownerMoveOnly: true,
    async run(H, actor, ctx) {
      const stat = H.zone.isClose(ctx.toZone) ? "quick" : H.zone.isRanged(ctx.toZone) ? "sharp" : "";
      if (!stat) return;
      const bonus = actor.getFlag("hollows", flag) || {};
      if (bonus[stat]) return;
      await actor.setFlag("hollows", flag, { ...bonus, [stat]: 2 });
      await H.chat.post(actor.name + " gains +2 " + stat + " until their next turn (Skirmisher).", actor);
    },
  },
  bonus: {
    hook: "statModifier",
    run: (H, actor, ctx) => actor.getFlag("hollows", flag)?.[ctx.stat] || 0,
  },
  clear: {
    hook: "startOfTurn", stage: "cleanup",
    run: (H, actor) => actor.unsetFlag("hollows", flag),
  },
  combat: {
    hook: "interceptor", event: "combat-reset-hunter",
    run: (H, actor) => actor.unsetFlag("hollows", flag),
  },
};

return {
  heal: {
    hook: "onAttackResult",
    timing: "afterDamageApplied",
    damageType: "Wounds",
    active(H, actor, ctx) { return ctx.weapon?.id === ctx.item.id; },
    async run(H, actor) {
      await H.resource.adjust(actor, { wounds: 1 });
      await H.chat.post("Wicked: heal 1 Wound.", actor);
    },
  },
};

return {
  bleeding: {
    hook: "onAttackResult", timing: "afterDamageApplied", damageType: "Wounds", weaponType: "Knife",
    async run(H, actor, ctx) {
      if (ctx.targetType !== "entity" || H.condition.has(ctx.targetActor, "bleeding")) return;
      await H.condition.set(ctx.targetActor, "bleeding", true);
      await H.chat.post(ctx.targetActor.name + " begins Bleeding.", ctx.targetActor);
    },
  },
};

if (!(H.zone.isClose(H.zone.of(actor)) && H.actors.entity()?.statuses.has("bleeding"))) return false;
await H.resource.adjust(actor, { resolve: 2 });
await H.chat.post(`${actor.name} restores 2 Resolve (Anointed).`, actor);

async function becomeReady(H, actor) {
  await H.condition.set(actor, "ready", true);
  await H.chat.post("Silk: become Ready.", actor);
}
return {
  cover: {
    hook: "onEvent",
    eventType: "takeCover",
    async run(H, actor) {
      if (H.condition.has(actor, "ready")) return;
      await becomeReady(H, actor);
    },
  },
  move: {
    hook: "onMove",
    ownerMoveOnly: true,
    async promptOnPlayer(H, actor) {
      if (H.condition.has(actor, "ready")) return false;
      if (!await H.ask.confirm({
        title: "Silk Armour",
        bodyHtml: "<p>Was this a Move manoeuvre?</p>",
        yesLabel: "Become Ready",
        noLabel: "Cancel",
      })) return false;
      await becomeReady(H, actor);
      return true;
    },
  },
};

function self(H, actor, ctx) { return actor === ctx.carrier && actor; }
function ready(H, actor) {
  if (actor.system.health.resolve.value <= 0) return;
  return H.condition.set(actor, "ready", true);
}
function unready(H, actor) {
  return H.condition.set(actor, "ready", false, { skipReactionDispatch: true });
}
return {
  combat: { hook: "interceptor", event: "combat-start-hunter", matchCarrier: self, run: ready },
  guard: { hook: "onEvent", eventType: "guard", run: ready },
  support: { hook: "interceptor", event: "support-recovery", matchCarrier: self, run: ready },
  broken: {
    hook: "interceptor", event: "hunter-broken", matchCarrier: self,
    async run(H, actor) {
      if (!H.condition.has(actor, "ready")) return;
      await unready(H, actor);
      await H.chat.post(actor.name + " becomes Unready (Broken).", actor);
    },
  },
  removed: {
    hook: "interceptor", event: "weapon-removed",
    async run(H, actor) {
      if (!H.weapon.equipped(actor, "Armour")) await unready(H, actor);
    },
  },
};

return {
  grant: {
    hook: "applyToZone",
    label: "Control: Grant Manoeuvre",
    subSelect: {
      name: "action",
      label: "Manoeuvre",
      options: [
        { value: "reload", label: "Reload" },
        { value: "take-cover", label: "Take Cover" },
        { value: "move", label: "Move" },
      ],
    },
    run: async (H, actor, ctx) => {
      await H.chat.post(actor.name + " expends Ready to grant " + ctx.target.name + " an immediate manoeuvre (Control).", actor);
      await H.actions.grantManoeuvre(ctx.target, ctx.payload.action);
    },
  },
  shift: {
    hook: "endOfTurn",
    run: (H, actor) => {
      if (!H.condition.has(actor, "ready")) return false;
      return H.threat.shift(actor, {
        amount: 1, sourceConstraint: "sameOrAdjacent", destConstraint: "adjacentToSource",
        excludeSupport: true, label: "Control: Shift Threat", reason: "Control",
      });
    },
  },
};

function self(H, actor, ctx) { return actor === ctx.carrier && actor; }
async function clearFocus(H, actor, reason) {
  if (!H.resource.focusCount(actor)) return;
  await H.resource.setFocus(actor, 0);
  if (reason) await H.chat.post(actor.name + " loses all Focus (" + reason + ").", actor);
}
return {
  focus: { hook: "resourceLimit", run: (H, actor, ctx) => ctx.resource === "focus" ? Math.max(ctx.value, 5) : ctx.value },
  combat: { hook: "interceptor", event: "combat-start-hunter", matchCarrier: self, run: (H, actor) => clearFocus(H, actor) },
  broken: { hook: "interceptor", event: "hunter-broken", matchCarrier: self, run: (H, actor) => clearFocus(H, actor, "Broken") },
  support: {
    hook: "interceptor", event: "hunter-zone-changed", matchCarrier: self,
    run: (H, actor, ctx) => ctx.toZone === "Support" ? clearFocus(H, actor, "entered Support") : null,
  },
};

const focusCost = (root, { focusCount }) => Math.min(focusCount,
  Math.max(0, Math.floor(Number(root.querySelector("[name=aimFocus]").value) || 0)));
return {
  attack: {
    hook: "attackOptions",
    run: () => ({
      dialogHtml: () => "<div class='form-group'><label>Aim For the Head: spend Focus for +1/+1 each</label><input type='number' name='aimFocus' min='0' value='0'></div>",
      focusCost,
      prepare(root, ctx) {
        const aim = root.querySelector("[name=aimFocus]");
        aim.max = ctx.focusCount;
        aim.disabled = ctx.focusCount <= 0;
        aim.addEventListener("input", ctx.updateFocusCost);
      },
      damageBonus(root, actor, state) {
        const spend = focusCost(root, state);
        if (!spend) return;
        state.damageResolve += spend;
        state.damageWounds += spend;
        state.cardLines.push("<div><strong>Aim For the Head:</strong> spent " + spend + " Focus for +" + spend + "/+" + spend + " damage.</div>");
      },
    }),
  },
};

return {
  advantage: {
    hook: "attackRoll",
    when(H, actor, ctx) {
      return (ctx.weapon?.id === ctx.item.id) && H.zone.isClose(ctx.zone);
    },
  },
};

function self(H, actor, ctx) { return actor === ctx.carrier && actor; }
async function load(H, actor, ctx) {
  await ctx.item.update({ "system.loaded": true });
}
return {
  combat: { hook: "interceptor", event: "combat-start-hunter", matchCarrier: self, run: load },
  support: { hook: "interceptor", event: "support-recovery", matchCarrier: self, run: load },
};

if (ctx.result !== "miss") return false;
await H.resource.adjust(actor, { resolve: -1 });
await H.chat.post(`${actor.name} suffers 1 Resolve (Frantic).`, actor);
await H.effects.apply([{ type: "damageEntity", resolve: 2, label: "Frantic" }], ctx);

return {
  guard: {
    hook: "onEvent",
    eventType: "guard",
    async promptOnPlayer(H, actor) {
      const allies = H.actors.hunters().filter(hunter => (hunter.id !== actor.id) && !H.condition.has(hunter, "dead"));
      const targetId = await H.ask.one({
        title: "Sacred",
        label: "Choose a Hunter to restore 1 Resolve",
        options: allies.map(hunter => ({ value: hunter.id, label: hunter.name })),
      });
      if (!targetId) return false;
      const target = allies.find(hunter => hunter.id === targetId);
      await H.resource.adjust(target, { resolve: 1 });
      await H.chat.post(`${target.name} restores 1 Resolve (Sacred).`, actor);
      return true;
    },
  },
};

if (ctx.result !== "hit") return false;
await H.effects.apply(
  [
    {
      type: "removeThreat",
      amount: { fromDamageType: { Wounds: 4, default: 2 } },
      zone: "selfOrAdjacent",
    },
  ],
  ctx,
);

return {
  absorb: {
    hook: "onEvent",
    eventType: "incomingEntityWoundDamage",
    async promptOnPlayer(H, actor) {
      if (!H.condition.has(actor, "ready")) return false;
      if (!await H.ask.confirm({
        title: "Metal Armour",
        bodyHtml: "<p>Expend Ready to reduce Wound damage by 1?</p>",
        yesLabel: "Expend Ready",
        noLabel: "Keep Ready",
      })) return false;
      await H.condition.set(actor, "ready", false);
      await H.chat.post("Metal: expend Ready to reduce Wound damage by 1.", actor);
      return { damageReduction: 1 };
    },
  },
};

function self(H, actor, ctx) { return actor === ctx.carrier && actor; }
function ready(H, actor) {
  if (actor.system.health.resolve.value <= 0) return;
  return H.condition.set(actor, "ready", true);
}
function unready(H, actor) {
  return H.condition.set(actor, "ready", false, { skipReactionDispatch: true });
}
return {
  combat: { hook: "interceptor", event: "combat-start-hunter", matchCarrier: self, run: ready },
  guard: { hook: "onEvent", eventType: "guard", run: ready },
  support: { hook: "interceptor", event: "support-recovery", matchCarrier: self, run: ready },
  broken: {
    hook: "interceptor", event: "hunter-broken", matchCarrier: self,
    async run(H, actor) {
      if (!H.condition.has(actor, "ready")) return;
      await unready(H, actor);
      await H.chat.post(actor.name + " becomes Unready (Broken).", actor);
    },
  },
  removed: {
    hook: "interceptor", event: "weapon-removed",
    async run(H, actor) {
      if (!H.weapon.equipped(actor, "Armour")) await unready(H, actor);
    },
  },
};

return {
  guard: {
    hook: "applyToZone", label: "Bulwark: Grant Guard",
    async run(H, actor, ctx) {
      await H.chat.post(`${actor.name} expends Ready to grant ${ctx.target.name} an immediate Guard (Bulwark).`, actor);
      await H.actions.grantManoeuvre(ctx.target, "guard");
    },
  },
  bonus: {
    hook: "onEvent", event: { type: "guard", scope: "zoneMate" }, group: "armour.t1.bulwark",
    promptOnPlayer(H, actor, ctx) {
      return H.condition.has(ctx.carrier, "ready");
    },
    async applyOnGM(H, actor) {
      const result = await H.resource.adjust(actor, { resolve: 1 });
      if (result.resolve.changed) await H.chat.post(`${actor.name} gains +1 Resolve from Bulwark.`, actor);
    },
  },
};

return {
  reach: {
    hook: "activated", label: "Arms Reach", rateLimit: "oncePerRound",
    async run(H, actor) {
      const ctx = { actor };
      await H.effects.apply([
        { type: "pickAmount", requireMyTurn: true, maxResolve: true, maxZoneThreat: true,
          ctxKey: "spend", title: "Arms Reach", label: "Spend Resolve",
          description: "Spend Resolve to remove equal Threat in your area." },
        { type: "spendResolve", amount: { fromCtx: "spend" } },
        { type: "removeThreat", zone: "self", amount: { fromCtx: "spend" } },
      ], ctx);
      return !ctx._cancelled;
    },
  },
};

return {
  bonus: {
    hook: "attackDamage", aura: true, group: "spear.t1.decoy",
    run(H, actor, ctx) {
      const lane = { "Ranged Left": "Flank Left", "Ranged Front": "Front", "Ranged Right": "Flank Right" };
      const zone = lane[ctx.attackerZone];
      if (!zone) return;
      const carrier = H.zone.huntersIn(zone).some(h => h.id !== actor.id
        && ctx.carrierIds.includes(h.id));
      return carrier ? { resolve: 1, wounds: 1 } : null;
    },
  },
};
